<?php session_start();require_once __DIR__.'/config/database.php';$id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)exit('Product not found');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(empty($_SESSION['user'])){header('Location: login.php');exit;}$r=(int)($_POST['rating']??0);$t=trim($_POST['review_text']??'');if($r>=1&&$r<=5&&strlen($t)>=3){$s=$pdo->prepare('INSERT INTO reviews(product_id,user_id,rating,review_text) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),review_text=VALUES(review_text)');$s->execute([$id,$_SESSION['user']['id'],$r,$t]);$msg='Review saved!';}else $msg='Choose a rating and write a review.';}$s=$pdo->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE product_id=? ORDER BY created_at DESC');$s->execute([$id]);$reviews=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Product reviews</title><link rel="stylesheet" href="css/style.css"></head><body><main class="page-wrap"><h1><?= htmlspecialchars($p['name']) ?> — Reviews</h1><p>₹<?= number_format($p['price'],2) ?></p><p><?= htmlspecialchars($msg) ?></p><?php if(!empty($_SESSION['user'])): ?><form method="post"><input type="hidden" name="id" value="<?= $id ?>"><label>Rating <select name="rating" required><option value="">Choose</option><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>"><?= str_repeat('★',$i) ?></option><?php endfor; ?></select></label><p><textarea name="review_text" required minlength="3" maxlength="1000" placeholder="Write your review"></textarea></p><button class="btn">Submit review</button></form><?php else: ?><p><a href="login.php">Login</a> to write a review.</p><?php endif; ?><h2>Customer reviews (<?= count($reviews) ?>)</h2><?php foreach($reviews as $r): ?><article><b><?= htmlspecialchars($r['name']) ?></b> <span style="color:#e8a326"><?= str_repeat('★',(int)$r['rating']) ?></span><p><?= nl2br(htmlspecialchars($r['review_text'])) ?></p></article><hr><?php endforeach; ?><a href="products.php">Back to products</a></main></body></html>